referenceSolutions.javascript:
export function solve(capacity, operations) {
  const values = [];
  return operations.map(([op, value]) => {
    if (op === "push") {
      if (values.length === capacity) values.shift();
      values.push(value);
      return null;
    }
    if (op === "shift") return values.length ? values.shift() : null;
    return values.slice();
  });
}

